function renderDetail(){stopImageRefresh();
 if(widgetMode){
  stopOrbit();const s=resolveSystem(selected),valid=hasOrbitChart(s)&&systemFocused;
  document.body.classList.toggle('orbit-paused',orbitPaused);
  if(widgetRegion){
   $('mapArea').classList.remove('system-focused');
   $('systemFocus').innerHTML='';
   $('systemFocus').classList.add('hidden');
   $('detail').innerHTML='';
   $('map').setAttribute('aria-label',(DATA.regions[widgetRegion]?.name||'Federation overview')+' regional chart. Select a system or world to open its article.');
   for(const node of document.querySelectorAll('[data-region], [data-region-shell]')){
    const region=node.dataset.region||node.dataset.regionShell;
    node.style.display=widgetRegion==='all'||region===widgetRegion?'':'none';
   }
   return;
  }
  $('mapArea').classList.add('system-focused');$('systemFocus').classList.remove('hidden');$('detail').innerHTML='';
  $('systemFocus').innerHTML=valid?`<div class="focus-visual">${silentDecoration(s)}<svg id="orbitDiagram" class="orbit-diagram" viewBox="0 0 760 580" tabindex="0" role="group" aria-label="${esc(planetFocus||s.name)} orbital widget. Focus this diagram and press Space to pause or play. Names and symbols open Codex articles."></svg></div>`:'<p class="widget-error" role="status">Choose a catalogued region, system, or planet for this widget.</p>';
  if(valid){mountSystem(s);const chart=$('orbitDiagram');chart.onkeydown=e=>{if(e.target===chart&&e.key===' '){e.preventDefault();toggleAtlasMotion('orbitDiagram')}}}
  return;
 }
 const focusScroll=$('systemFocus').scrollTop;stopOrbit();document.body.classList.toggle('orbit-paused',orbitPaused);
 const s=allRecords.find(x=>x.id===selected);selectedWorld=resolveObjectName(s,selectedWorld);syncSystemFocus(s);$('mobileInspect').textContent=s?(selectedWorld||s.name)+' dossier ↗':'Region dossier ↗';
 if(!s){const r=DATA.regions[view];$('detail').innerHTML=`<div class="detail-top"><span class="eyebrow">Regional dossier</span><button class="detail-close" aria-label="Close dossier">×</button></div><div class="empty-detail"><div class="eyebrow">${view==='all'?'Territorial register':'Chart summary'}</div><h2>${link(r?r.name:'{{brand|jsstr}}')}</h2>${r?.silentPresence?`<div class="sector-tier-key">${Object.keys(TIER_NAMES).map(tier=>tierMarkup({tier})).join('')}</div>`:''}${r?.formerEmpire?`<p class="affiliation">Former territory of ${link(r.formerEmpire)}</p>`:''}${r?.historicalSource?link(r.historicalSource,'Read the campaign account ↗','region-link'):''}${r?.capitalPlanet?`<p class="affiliation">Capital system: ${systemLink(resolveSystem('Xai'))} · Capital world: ${link(r.capitalPlanet)}</p>`:''}<p>${r?esc(r.description):'Jurah Makor and Jurah Lendor form the paired heartland. The settlement register includes 205 inhabited worlds or colony sites in 137 systems. Drayson and evacuated holdings are counted separately. The outer-region placements are schematic. The Codex describes more than 200 controlled worlds across a 224-lightyear span. This chart is a selective register, not a complete census.'}</p><div class="region-stat"><b>${view==='all'?DATA.systems.length:DATA.systems.filter(s=>s.region===view).length}</b><span>charted system markers</span></div>${r?link(r.name,'Open region in the Codex ↗','region-link'):link('Territory of the Kadaymian Federation','Territorial register ↗','region-link')}${r?.file?link('File:'+r.file,'Original regional map ↗','region-link'):''}${view==='all'?DATA.unplaced.filter(r=>r.unplottedSystem).map(r=>`<div class="orbit-site-heading">CLASSIFIED SYSTEMS</div><button class="focus-world" id="classifiedSystem" data-system="${esc(r.id)}">${esc(r.name)} · open system diagram</button>`).join(''):''}<p class="tiny">Select a star to inspect its worlds and sources. Names on the map open their matching Codex articles.</p>${view==='all'?`<h3>Known neighbor</h3>${link('Interstellar Union of Liberated Republics','I.U.L.R. · spinward','region-link')}<p class="tiny">Diplomatic sources conflict: the Union article describes treaty peace, while the relations page describes active war. No current battle line is inferred.</p>`:''}<div class="note">Local layouts follow published regional maps where available. Region spacing and outlines are schematic; no distances or travel times are implied.</div></div>`;bindDetail();return}
 const w=worldRecord(s,selectedWorld),display=w?selectedWorld:hasOrbitChart(s)?systemArticleTitle(s):s.name;
 const status=w?w.tag:s.centralBodyType==='silent-darkened'?'Dead system · Silent-darkened star':s.centralBodyType==='black-hole'?'Black hole system':EXOTIC_TYPES[s.centralBodyType]?EXOTIC_TYPES[s.centralBodyType]+' system':s.kind==='classified'?'Classified location':s.kind==='hazard'?'Hazard register':s.kind==='uncertain'?'Unresolved chart marker':s.kind==='context'?'Neighboring system':s.kind==='neutral'?'Independent / CONCORD':s.region?'Federation system':'Unplotted holding';
 $('detail').innerHTML=`<div class="detail-top"><span class="eyebrow">Location dossier</span><button class="detail-close" aria-label="Close dossier">×</button></div>${hasOrbitChart(s)?(systemFocused?'<div class="focused-dossier">System explorer is open in the main chart.<button id="returnSystem">← Return to '+(s.unplottedSystem?'chart':'region view')+'</button></div>':systemView(s)):`<div class="no-hero"><div class="orb"></div></div>${s.silentPresence?'<p class="silent-status" role="status">Silent activity detected · signal interference</p>':''}`}<div class="detail-content">${referenceImage(w||systemArticleRecord(s),display)}<div class="type" id="dossierType" data-atlas-type="${esc(status.toUpperCase())}">${esc(status.toUpperCase())}</div><h2>${link(display)}</h2>${(w||s).nickname?`<p class="nickname">${esc((w||s).nickname)}</p>`:''}<div class="system-subtitle">${s.region?`${systemLink(s)} / ${link(DATA.regions[s.region].name)}`:(s.unplottedSystem?systemLink(s)+' / ':'')+'POSITION '+(s.kind==='classified'?'CLASSIFIED':'UNSPECIFIED')}</div>${tierMarkup(s)}<div id="bodyFacts">${bodyFacts(s,w,liveImages.get(currentImageTitle(w||systemArticleRecord(s),display)))}</div>${focusableWorld(s,selectedWorld)?`<button id="focusPlanet" class="focus-world">◎ &nbsp; ${planetFocus===selectedWorld?'Viewing local orbit':'Focus planet & satellites'}</button>`:''}<p class="description">${esc(w?w.description:s.description)}</p>${!systemFocused?notableSitesMarkup(s):''}${s.worlds.length&&!hasOrbitChart(s)?`<h3>Associated sites</h3>${s.worlds.map(n=>`<div class="world-chip ${selectedWorld===n?'active':''}">${link(n)}<button data-world="${esc(n)}" aria-label="View ${esc(n)} dossier">VIEW</button></div>`).join('')}`:''}${(w?.links||s.links||[]).length?`<h3>Related locations & records</h3><div class="link-pills">${(w?.links||s.links).map(n=>link(n)).join('')}</div>`:''}<a href="${url(display)}" target="_blank" rel="noopener" class="codex-button">Open ${esc(display)} in Codex ↗</a>${(s.notes||[]).map(n=>`<div class="note">${esc(n)}</div>`).join('')}<div class="source-line">${'Source: '+(w?.sourceNote?esc(w.sourceNote)+' · ':'')}${w?.sourceSection?`<a href="${esc(url(w.source)+'#'+encodeURIComponent(w.sourceSection))}" target="_blank" rel="noopener">${esc(w.source)} · station register</a>`:link(w?w.source:s.source)}${s.region&&s.source!==(w?.source)?'<br>Chart / context: '+link(s.source):''}<br>${s.unplottedSystem?'Coordinates withheld. Regional assignment unknown.':s.centralBodyType==='black-hole'||s.schematicPosition?'System position is schematic.':s.region&&s.region!=='narthezk'?'System position follows the regional chart.':s.kind==='classified'?'Coordinates deliberately withheld.':s.region?'No measured coordinates available.':'No map coordinates assigned.'}</div></div>`;
 bindDetail();bindSystemControls();mountSystem(s);applySystemZoom();$('systemFocus').scrollTop=focusScroll;refreshVisibleImage();
}
